<?php
$char=$PCC->tableExists('rp_characters');$lastOnline=$PCC->columnExists('users','last_online');$cols='u.id,u.username,u.look,u.rank,u.online'.($lastOnline?',u.last_online':',NULL last_online').($char?',c.first_name,c.last_name,c.citizen_id':',NULL first_name,NULL last_name,NULL citizen_id');$join=$char?' LEFT JOIN rp_characters c ON c.user_id=u.id':'';$rows=$DB->PreparedAll("SELECT $cols FROM users u$join WHERE u.online='1' ORDER BY u.username");
?>
<section class="pcc-alert info"><i class="fas fa-satellite-dish"></i><div><strong>Source session actuelle</strong><p><code>users.online</code> est le signal fiable exposé au CMS. La room courante et l’heure exacte de début de session ne sont pas persistées de façon fiable dans la base auditée ; elles restent donc absentes au lieu d’être devinées.</p></div></section>
<section class="pcc-panel"><div class="pcc-panel-head"><div><h2>Sessions actives</h2><p>Comptes marqués online par l’ÉMU.</p></div><span class="pcc-badge success"><?php echo $number(count($rows));?> EN LIGNE</span></div><div class="pcc-table-wrap"><table class="pcc-table"><thead><tr><th>Joueur</th><th>Nom RP</th><th>Citizen ID</th><th>Rôle</th><th>État</th><th>Room actuelle</th><th>Démarrage session</th><th></th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="8"><div class="pcc-empty compact"><strong>Aucune session active</strong></div></td></tr><?php endif;?><?php foreach($rows as $r):$rp=trim((string)$r['first_name'].' '.(string)$r['last_name']);?><tr><td><div class="pcc-user-cell"><img class="pcc-table-avatar" src="<?php echo $h($PCC->avatarUrl($r['look'],'s'));?>" alt=""><span><strong><?php echo $h($r['username']);?></strong><small class="pcc-subline">#<?php echo (int)$r['id'];?></small></span></div></td><td><?php echo $rp!==''?$h($rp):'—';?></td><td><code><?php echo $r['citizen_id']?$h($r['citizen_id']):'—';?></code></td><td><?php echo $h($PCC->roleName($r['rank']));?></td><td><span class="pcc-badge success">EN LIGNE</span></td><td><span class="pcc-muted">Non exposée au CMS</span></td><td><span class="pcc-muted">Non exposé</span></td><td><a class="pcc-button small secondary" href="<?php echo URL;?>/admin.php?page=player&id=<?php echo (int)$r['id'];?>">Fiche joueur</a></td></tr><?php endforeach;?></tbody></table></div></section>
